        // Mutant:   succeeds for any positive amount → ok = true
        // The rule: a sendTo to address(0) with positive amount must ALWAYS revert
        // (i.e. ok must be false)
        require(ok == false, "Rule violated: sendTo to address(0) must revert");
    }
}

